                    {% for row in doc.items %}
                    <tr>
                        <td style="font-size: 11px;color: black;text-align: right;border: 1px solid black;padding-left: 2px !important;">{% if row.taxable_value %} {{frappe.utils.fmt_money(row.taxable_value)}} {% endif %}</td>
                        <td style="font-size: 11px;color: black;text-align: right;border: 1px solid black;padding-left: 2px !important;">{% if row.sgst_amount %} {{frappe.utils.fmt_money(row.sgst_amount)}} {% endif %}</td>
                        <td style="font-size: 11px;color: black;text-align: right;border: 1px solid black;padding-left: 2px !important;">{% if row.cgst_amount %} {{frappe.utils.fmt_money(row.cgst_amount)}} {% endif %}</td>
