                        <td style="font-size: 11px;color: black;text-align: right;border: 1px solid black;padding-left: 2px !important;">{% if row.discount_amount %} {{frappe.utils.fmt_money(row.discount_amount)}} {% endif %}</td>
                        <td style="font-size: 11px;color: black;text-align: right;border: 1px solid black;padding-left: 2px !important;">{% if row.rate %} {{frappe.utils.fmt_money(row.rate)}} {% endif %}</td>
