                        <td style="font-size: 11px;color: black;text-align: right;border: 1px solid black;padding-left: 2px !important;">{% if row.amount %} {{frappe.utils.fmt_money(row.amount)}} {% endif %}</td>
                    </tr>
                    {% endfor %}
                </tbody>
            </table>
        </div>
    </div>
    <div style="width: 99%;float: left;margin-top: 2px;padding: 0 5px;margin-left: 3px;border: 1px solid black;border-radius: 5px;margin-bottom: 2px;">
        <div style="width: 30%;float: left;">
            <p style="font-size: 13px;color: black;font-weight: 600;text-align: left;">Generated By: {% if doc.company_gstin %} {{doc.company_gstin}} {% endif %}</p>
            <p style="font-size: 13px;color: black;font-weight: 600;text-align: left;">Print Date: </p>
        </div>
    </div>
</div>





